    var INJECTED = NO_REF_ERR + '\n\u26A0\uFE0F trigger-failed ' + DEAD_REF +
        ' \u2014 attempt 3/3 at 2026-10-16T13:00:00Z';
    var tfMod = loadModule('js/common/triggerFailures.js', makeRequire({}), {});

